"""Per-source counts for Wyscout and DFL, next to their published figures (``make report``)."""

from __future__ import annotations

from pathlib import Path

from rondo.core import store
from rondo.core.dfl_ingest import PUBLISHED as DFL_PUBLISHED
from rondo.core.wyscout_ingest import COMPETITIONS


def render(parquet: Path) -> str:
    """Render ``reports/sources_summary.md``."""
    con = store.connect()
    store.create_views(con, parquet)
    lines = [
        "# Wyscout and DFL data summary",
        "",
        "Generated by `make report` from `data/parquet/`. Don't edit by hand. Published figures "
        "come from Pappalardo et al. (2019), Table 1, and Bassek et al. (2025), Table 1.",
        "",
        "## Wyscout (2017/18 leagues, World Cup 2018, Euro 2016)",
        "",
        "| Competition | Matches | Published | Events | Published | Players in lineups | "
        "Published | SPADL actions |",
        "|---|---|---|---|---|---|---|---|",
    ]
    rows = con.execute(
        """select c.competition_id, c.name, count(distinct m.match_id),
                  (select count(*) from wy_events e join wy_matches mm using (match_id)
                   where mm.competition_id = c.competition_id),
                  (select count(distinct l.player_id) from wy_lineups l
                   join wy_matches mm using (match_id) where mm.competition_id = c.competition_id),
                  (select count(*) from spadl_actions a join wy_matches mm using (match_id)
                   where a.provider = 'wyscout' and mm.competition_id = c.competition_id)
           from wy_competitions c join wy_matches m using (competition_id)
           group by 1, 2 order by 2"""
    ).fetchall()
    tot = [0] * 7
    for cid, name, m, e, p, a in rows:
        _, pm, pe, pp = COMPETITIONS[cid]
        lines.append(f"| {name} | {m:,} | {pm:,} | {e:,} | {pe:,} | {p:,} | {pp:,} | {a:,} |")
        for i, v in enumerate((m, pm, e, pe, p, pp, a)):
            tot[i] += v
    lines.append("| **Total** | " + " | ".join(f"**{v:,}**" for v in tot) + " |")
    distinct = con.execute(
        "select (select count(distinct player_id) from wy_lineups), "
        "(select count(*) from wy_players)"
    ).fetchall()[0]
    lines += [
        "",
        f"Distinct players across all lineups: {distinct[0]:,}. Players in Wyscout's players file "
        f"(all with birth dates): {distinct[1]:,}. The players total above counts a player once "
        "per competition.",
        "",
        "## DFL tracking (2022/23)",
        "",
        "| Match | Home | Away | Date | Frames | Published | Object rows | Raw events | "
        "Published events | Players on sheet |",
        "|---|---|---|---|---|---|---|---|---|---|",
    ]
    rows = con.execute(
        """select m.match_id, any_value(m.home_team_name), any_value(m.away_team_name),
                  any_value(m.match_date), sum(m.n_frames),
                  (select count(*) from tracking_frames t where t.match_id = m.match_id),
                  (select count(*) from dfl_events e where e.match_id = m.match_id),
                  (select count(*) from dfl_lineups l where l.match_id = m.match_id)
           from tracking_meta m group by 1 order by 4, 1"""
    ).fetchall()
    tot = [0] * 6
    for mid, home, away, date, frames, objs, events, lineup in rows:
        pf, pe = DFL_PUBLISHED[mid]
        lines.append(
            f"| {mid} | {home} | {away} | {date} | {frames:,} | {pf:,} | {objs:,} | {events:,} | "
            f"{pe:,} | {lineup} |"
        )
        for i, v in enumerate((frames, pf, objs, events, pe, lineup)):
            tot[i] += v
    lines.append("| **Total** | | | | " + " | ".join(f"**{v:,}**" for v in tot) + " |")
    con.close()
    return "\n".join(lines) + "\n"
